// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 secondCaller) public {
        address caller1 = address(111);
        address caller2 = address(uint160(secondCaller));
        vm.assume(caller2 != caller1);
        vm.assume(caller2 != address(0));
        uint256 callValue = 10 ether;
        vm.deal(caller1, callValue);
        vm.deal(caller2, callValue);
        vm.warp(1000);
        vm.prank(caller1);
        (bool ok1,) = address(c).call{value: callValue}("");
        require(ok1, "first call must succeed");
        vm.prank(caller2);
        (bool ok2,) = address(c).call{value: callValue}("");
        assertTrue(!ok2);
    }
}
